/* engines/loader.js — part of the universal player. Generated by the one-off split;
 * every top-level name lives on the shared context P (see context.js). */
import { P } from "../context.js";

export function install(P) {


  function loadEngineCss(file, key) {
    if (P.loadedEngineCss.has(key)) return;
    P.loadedEngineCss.add(key);
    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.dataset.engineCss = key;
    link.href = P.VENDOR_BASE ? `${P.VENDOR_BASE}${file}` : `${P.basePrefix()}vendor/${file}`;
    document.head.appendChild(link);
  }

  function showEngineUi(engine) {
    if (!P.engineUi || !P.ENGINE_UI.has(engine)) return false;
    if (engine === "aplayer") P.loadEngineCss("aplayer.min.css", "aplayer");
    else if (engine === "mediaelement") P.loadEngineCss("mediaelementplayer.min.css", "mediaelement");
    else if (engine === "jplayer") P.loadEngineCss("jplayer.blue.monday.min.css", "jplayer");

    P.engineUi.hidden = false;
    P.engineUi.querySelectorAll("[data-engine-view]").forEach((view) => {
      view.hidden = view.dataset.engineView !== engine;
    });
    P.seek.hidden = true;
    P.waveform.hidden = true;
    P.setWaveMode(true);
    if (engine === "howler") P.startHowlerAnalyser();
    else P.stopHowlerAnalyser();
    return true;
  }

  function hideEngineUi() {
    P.stopHowlerAnalyser();
    if (!P.engineUi) return;
    P.engineUi.hidden = true;
    P.engineUi.querySelectorAll("[data-engine-view]").forEach((view) => { view.hidden = true; });
  }

  function stopHowlerAnalyser() {
    if (P.labRaf) { window.cancelAnimationFrame(P.labRaf); P.labRaf = 0; }
    try { P.labNode?.disconnect(); } catch {}
    try { P.labGain?.disconnect(); } catch {}
    P.labNode = null;
    P.labGain = null;
  }

  function startHowlerAnalyser() {
    if (P.labRaf || !P.$("labAnalyser")) return;
    const context = P.sharedAudioContext();
    if (!context) return;
    const main = P.ensureMainGain();
    const tapSource = main?.gain || P.mediaSourceNode;
    if (!tapSource) return;
    const canvas = P.$("labAnalyser");
    const ctx2d = canvas.getContext("2d");
    if (!ctx2d) return;
    const analyser = context.createAnalyser();
    analyser.fftSize = 1024;
    try {
      tapSource.connect(analyser);
      // If we tapped mainGainNode, audio already reaches destination.
      // Otherwise route through unity gain to keep element audible.
      if (!main?.gain) {
        P.labGain = context.createGain();
        P.labGain.gain.value = 1;
        analyser.connect(P.labGain);
        P.labGain.connect(P.outputDestination() || context.destination);
      }
    } catch {}
    P.labNode = analyser;

    const data = new Uint8Array(analyser.frequencyBinCount);
    const draw = () => {
      P.labRaf = window.requestAnimationFrame(draw);
      analyser.getByteTimeDomainData(data);
      const width = canvas.width;
      const height = canvas.height;
      ctx2d.fillStyle = P.cssVar("--bg-elevated-2") || "#141414";
      ctx2d.fillRect(0, 0, width, height);
      ctx2d.lineWidth = 2;
      ctx2d.strokeStyle = P.cssVar("--text") || "#ffffff";
      ctx2d.beginPath();
      const slice = width / data.length;
      let x = 0;
      let peak = 0;
      for (let i = 0; i < data.length; i++) {
        const value = data[i];
        const y = (value / 128) * (height / 2);
        if (i === 0) ctx2d.moveTo(x, y); else ctx2d.lineTo(x, y);
        peak = Math.max(peak, Math.abs(value - 128));
        x += slice;
      }
      ctx2d.stroke();
      const level = P.$("labAnalyserLevel");
      if (level) level.textContent = `${Math.round((peak / 128) * 100)}%`;
    };
    draw();
  }

  /* ---------- engine: WaveSurfer ---------- */

  function injectVendorScript(file) {
    return new Promise((resolve, reject) => {
      const script = document.createElement("script");
      script.src = P.VENDOR_BASE
        ? `${P.VENDOR_BASE}${file}`
        : `${P.basePrefix()}vendor/${file}`;
      script.onload = () => resolve();
      script.onerror = () => reject(new Error(`${file} not loaded`));
      document.head.appendChild(script);
    });
  }

  function loadWaveSurferScript() {
    if (window.WaveSurfer) return Promise.resolve();
    if (!P.scriptPromise) P.scriptPromise = P.injectVendorScript("wavesurfer.min.js");
    return P.scriptPromise;
  }

  function loadPeaksScript() {
    if (window.peaks) return Promise.resolve();
    if (!P.peaksScriptPromise) P.peaksScriptPromise = P.injectVendorScript("peaks.min.js");
    return P.peaksScriptPromise;
  }

  function loadHowlerScript() {
    if (window.Howl && window.Howler) return Promise.resolve();
    if (!P.howlerScriptPromise) P.howlerScriptPromise = P.injectVendorScript("howler.min.js");
    return P.howlerScriptPromise;
  }

  function loadWavizScript() {
    if (P.wavizConstructor()) return Promise.resolve();
    if (!P.wavizScriptPromise) P.wavizScriptPromise = P.injectVendorScript("waviz.min.js");
    return P.wavizScriptPromise;
  }

  // The UMD build exposes a namespace: window.Waviz.Waviz (also .default).
  function wavizConstructor() {
    const ns = window.Waviz;
    if (typeof ns === "function") return ns;
    return ns && (typeof ns.Waviz === "function" ? ns.Waviz : ns.default);
  }

  function loadMediaElementScript() {
    if (window.MediaElement) return Promise.resolve();
    if (!P.mediaElementScriptPromise) {
      P.mediaElementScriptPromise = P.injectVendorScript("mediaelement-and-player.min.js");
    }
    return P.mediaElementScriptPromise;
  }

  function loadAmplitudeScript() {
    if (window.Amplitude) return Promise.resolve();
    if (!P.amplitudeScriptPromise) P.amplitudeScriptPromise = P.injectVendorScript("amplitude.min.js");
    return P.amplitudeScriptPromise;
  }

  function loadAPlayerScript() {
    if (window.APlayer) return Promise.resolve();
    if (!P.aplayerScriptPromise) P.aplayerScriptPromise = P.injectVendorScript("aplayer.min.js");
    return P.aplayerScriptPromise;
  }

  // jPlayer is a jQuery plugin, and the pinned jQuery 2 build keeps the old
  // .bind()/.unbind() API that jPlayer 2.9.2 was written against.
  function loadJPlayerScript() {
    const ensureJQuery = window.jQuery
      ? Promise.resolve()
      : (P.jqueryScriptPromise || (P.jqueryScriptPromise = P.injectVendorScript("jquery.min.js")));
    return ensureJQuery.then(() => {
      if (window.jQuery?.fn?.jPlayer) return;
      if (!P.jplayerScriptPromise) P.jplayerScriptPromise = P.injectVendorScript("jquery.jplayer.min.js");
      return P.jplayerScriptPromise;
    });
  }
  Object.assign(P, { loadEngineCss, showEngineUi, hideEngineUi, stopHowlerAnalyser, startHowlerAnalyser, injectVendorScript, loadWaveSurferScript, loadPeaksScript, loadHowlerScript, loadWavizScript, wavizConstructor, loadMediaElementScript, loadAmplitudeScript, loadAPlayerScript, loadJPlayerScript });
}
